<section class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2">Instructor dashboard</h1><p class="text-muted">Manage your course catalogue.</p></div><span class="badge text-bg-info">Instructor</span></div><div class="card"><div class="card-body"><div class="d-flex justify-content-between mb-3"><h2 class="h5 mb-0">My courses</h2><a href="/instructor/courses/create" class="btn btn-primary btn-sm">Create course</a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Title</th><th>Price</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if (!$courses): ?><tr><td colspan="4" class="text-muted">No courses created yet.</td></tr><?php endif; ?><?php foreach ($courses as $course): ?><tr><td><?= e($course['title']) ?></td><td>$<?= e(number_format((float) $course['price'], 2)) ?></td><td><span class="badge text-bg-secondary"><?= e($course['status']) ?></span></td><td><a href="/instructor/courses/edit?id=<?= e((string) $course['id']) ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div></div></div></section>